package com.acme.shortener.abuse;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.acme.shortener.TestcontainersConfiguration;
import com.acme.shortener.url.HostResolver;
import java.net.InetAddress;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Import;
import org.springframework.context.annotation.Primary;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;
import tools.jackson.databind.json.JsonMapper;

/**
 * Abuse protection end to end over real Postgres and Redis: blocked destination domains are refused
 * at creation (400 invalid-url with a reason), and an admin can flag a link, which then answers 451
 * even if it was cached. Covers AC-1 to AC-7.
 */
@SpringBootTest(
    properties = {
      "shortener.abuse.blocked-domains=evil.test,Phish.TEST",
      "shortener.abuse.admin-keys=other" // the "other-key" API key, see test config
    })
@AutoConfigureMockMvc
@Import({TestcontainersConfiguration.class, AbuseIT.PublicDns.class})
class AbuseIT {

  private static final String OWNER = "test-key"; // owner "tester"
  private static final String ADMIN = "other-key"; // owner "other", an admin here

  @Autowired MockMvc mvc;
  @Autowired JsonMapper json;

  /** Every host resolves to a public address, without the network. */
  @TestConfiguration
  static class PublicDns {
    @Bean
    @Primary
    HostResolver publicHostResolver() {
      return host -> List.of(InetAddress.getByName("93.184.215.14"));
    }
  }

  // ---- destinations refused at creation ----

  @Test
  void blockedDomainsAndTheirSubdomainsAreRefused() throws Exception {
    for (String url :
        new String[] {
          "https://evil.test/login", "https://www.EVIL.test/x", "https://a.b.phish.test/"
        }) {
      invalidUrl(create(url), "BLOCKED_DOMAIN");
    }
    create("https://notevil.test/").andExpect(status().isCreated()); // a suffix is not a subdomain
  }

  // ---- flagging ----

  @Test
  void aFlaggedLinkAnswers451AtOnceEvenIfCached() throws Exception {
    String code = code(create("https://example.com/flag-me"));
    mvc.perform(get("/" + code)).andExpect(status().isFound()); // now cached

    mvc.perform(post("/api/v1/admin/links/" + code + "/flag").header("X-API-Key", ADMIN))
        .andExpect(status().isNoContent());

    problem(mvc.perform(get("/" + code)), 451, "link-unavailable");
    problem(mvc.perform(get("/" + code)), 451, "link-unavailable"); // not cached as 404 either
    mvc.perform(get("/api/v1/links/" + code).header("X-API-Key", OWNER))
        .andExpect(status().isOk())
        .andExpect(jsonPath("$.status").value("FLAGGED"));
    mvc.perform(post("/api/v1/admin/links/" + code + "/flag").header("X-API-Key", ADMIN))
        .andExpect(status().isNoContent()); // idempotent
  }

  @Test
  void onlyAdminKeysMayFlag() throws Exception {
    String code = code(create("https://example.com/not-mine-to-flag"));

    problem(
        mvc.perform(post("/api/v1/admin/links/" + code + "/flag").header("X-API-Key", OWNER)),
        403,
        "forbidden");
    problem(mvc.perform(post("/api/v1/admin/links/" + code + "/flag")), 401, "unauthorized");
    mvc.perform(get("/" + code)).andExpect(status().isFound()); // unchanged
  }

  @Test
  void unknownAndDeletedLinksCannotBeFlagged() throws Exception {
    problem(
        mvc.perform(post("/api/v1/admin/links/nosuch1/flag").header("X-API-Key", ADMIN)),
        404,
        "link-not-found");

    String code = code(create("https://example.com/deleted-first"));
    mvc.perform(
            org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete(
                    "/api/v1/links/" + code)
                .header("X-API-Key", OWNER))
        .andExpect(status().isNoContent());
    problem(
        mvc.perform(post("/api/v1/admin/links/" + code + "/flag").header("X-API-Key", ADMIN)),
        404,
        "link-not-found");
  }

  // ---- helpers ----

  private ResultActions create(String url) throws Exception {
    return mvc.perform(
        post("/api/v1/links")
            .header("X-API-Key", OWNER)
            .contentType(MediaType.APPLICATION_JSON)
            .content(json.writeValueAsString(Map.of("url", url))));
  }

  private String code(ResultActions created) throws Exception {
    String body =
        created.andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
    return (String) json.readValue(body, Map.class).get("code");
  }

  private static void invalidUrl(ResultActions result, String reason) throws Exception {
    problem(result, 400, "invalid-url").andExpect(jsonPath("$.reason").value(reason));
  }

  private static ResultActions problem(ResultActions result, int status, String slug)
      throws Exception {
    return result
        .andExpect(status().is(status))
        .andExpect(
            org.springframework.test.web.servlet.result.MockMvcResultMatchers.content()
                .contentTypeCompatibleWith("application/problem+json"))
        .andExpect(jsonPath("$.type").value("/problems/" + slug));
  }
}

package com.acme.shortener.url;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.net.InetAddress;
import java.util.List;
import java.util.Set;
import org.junit.jupiter.api.Test;

/** Blocked domains (AC-1, AC-2): matching by domain and subdomain only. */
class DestinationRulesTest {

  private final UrlValidator validator =
      new UrlValidator(
          2048,
          Set.of("http", "https"),
          true,
          "http://sho.rt",
          host -> List.of(InetAddress.getByName("93.184.215.14")),
          Set.of("Evil.Test.", " "));

  @Test
  void aBlockedDomainMatchesItselfAndItsSubdomainsCaseInsensitively() {
    for (String url : List.of("https://evil.test", "https://x.y.EVIL.test./a")) {
      assertThatThrownBy(() -> validator.validate(url))
          .isInstanceOfSatisfying(
              InvalidUrlException.class,
              e -> assertThat(e.reason()).isEqualTo(InvalidUrlException.Reason.BLOCKED_DOMAIN));
    }
    assertThat(validator.validate("https://notevil.test/").getHost()).isEqualTo("notevil.test");
    assertThat(validator.validate("https://evil.test.example.com/").getHost())
        .isEqualTo("evil.test.example.com");
  }

  @Test
  void withoutRulesNothingExtraIsRefused() {
    UrlValidator plain =
        new UrlValidator(
            2048,
            Set.of("https"),
            true,
            "http://sho.rt",
            host -> List.of(InetAddress.getByName("93.184.215.14")));

    assertThat(plain.validate("https://bit.ly/abc").getHost()).isEqualTo("bit.ly");
  }
}
